parameters.jsCode:
// Change these for your hospital.
return [{
  json: {
    lat: 26.85,
    lon: 80.95,
    // Optional live traffic: a free key from developer.tomtom.com.
    // Leave empty and OPD Saathi estimates traffic from the time of day and rain.
    tomtomKey: '',
    // A busy road near the hospital ("lat,lon") to measure traffic on.
    roadPoint: '26.8467,80.9462',
  },
}];

// Builds the conditions in the shape OPD Saathi expects (see client/src/lib/model.js).
const pad = (n) => String(n).padStart(2, '0');
const w = $('Weather').first().json;
let a = null;
let tt = null;
try { a = $('Air quality').first().json; } catch {}
try { tt = $('Traffic').first().json; } catch {}

const hourly = {};
w.hourly.time.forEach((t, i) => {
  hourly[t.slice(0, 13)] = {
    temp: w.hourly.temperature_2m[i],
    rain: w.hourly.precipitation[i] ?? 0,
    rainProb: w.hourly.precipitation_probability?.[i] ?? null,
    code: w.hourly.weather_code[i],
    aqi: null,
  };
});
if (a && a.hourly && a.hourly.time) {
  a.hourly.time.forEach((t, i) => {
    const k = t.slice(0, 13);
    if (hourly[k]) hourly[k].aqi = a.hourly.us_aqi[i];
  });
}
const daily = {};
w.daily.time.forEach((d, i) => {
  let aqi = null;
  for (let h = 8; h <= 14; h++) {
    const v = hourly[`${d}T${pad(h)}`]?.aqi;
    if (v != null) aqi = Math.max(aqi ?? 0, v);
  }
  daily[d] = {
    tMax: w.daily.temperature_2m_max[i],
    tMin: w.daily.temperature_2m_min[i],
    rain: w.daily.precipitation_sum[i] ?? 0,
    rainProb: w.daily.precipitation_probability_max?.[i] ?? null,
    code: w.daily.weather_code[i],
    aqi,
  };
});

// Traffic: how much longer the road takes now than when it is empty.
let traffic = null;
const f = tt && tt.flowSegmentData;
if (f && f.freeFlowTravelTime) {
  const ratio = f.currentTravelTime / f.freeFlowTravelTime;
  traffic = {
    level: Math.max(0, Math.min(1, (ratio - 1) / 1.2)),
    ratio: Math.round(ratio * 100) / 100,
    currentSpeed: f.currentSpeed,
    freeFlowSpeed: f.freeFlowSpeed,
    at: Date.now(),
    source: 'tomtom',
  };
}

return [{
  json: {
    source: 'n8n',
    fetchedAt: Date.now(),
    now: {
      temp: w.current?.temperature_2m ?? null,
      rain: w.current?.precipitation ?? 0,
      code: w.current?.weather_code ?? null,
      humidity: w.current?.relative_humidity_2m ?? null,
      wind: w.current?.wind_speed_10m ?? null,
      aqi: a?.current?.us_aqi ?? null,
    },
    hourly,
    daily,
    traffic,
  },
}];
